import { readFileSync } from 'fs';
import { join } from 'path';
import type { FastifyInstance } from 'fastify';

/** One WhatsApp-gateway API from the functional spec (section 8 annex). Generated by dhruva-platform/tools/spec-sync. */
export interface SpecEndpoint {
  m: string;
  p: string;
  why: string;
  req: string[];
  src: string;
}

// src/spec and dist/spec both sit two levels below the repo root.
export const loadCatalog = (): SpecEndpoint[] =>
  JSON.parse(readFileSync(join(__dirname, '..', '..', 'spec', 'endpoints.json'), 'utf8')) as SpecEndpoint[];

export const toFastifyPath = (p: string) => p.replace(/:/g, '::').replace(/\{(\w+)\}/g, ':$1');

/**
 * Registers a 501 stub for every spec API the gateway does not implement yet. Call after the real
 * routes are registered: a route that already exists is never stubbed.
 */
export function registerSpecStubs(app: FastifyInstance) {
  const endpoints = loadCatalog();
  let stubbed = 0;
  for (const e of endpoints) {
    const url = toFastifyPath(e.p);
    if (app.hasRoute({ method: e.m as 'GET', url })) continue;
    app.route({
      method: e.m as 'GET',
      url,
      handler: async (_req, reply) =>
        reply.code(501).send({
          statusCode: 501,
          error: 'Not Implemented',
          message: `Stub: ${e.why}`,
          endpoint: `${e.m} ${e.p}`,
          requirements: e.req,
          source: e.src,
        }),
    });
    stubbed++;
  }
  const coverage = { endpoints: endpoints.length, stubbed, implemented: endpoints.length - stubbed };
  app.get('/internal/spec/coverage', async () => coverage);
  return coverage;
}
